bounded_host_request.command:
set -eu
cid=gace-createvdobot-videobot-poll-1
test "$(docker inspect "$cid" --format '{{.State.Running}}')" = true || exit 41
docker exec -i -w /opt/videobot "$cid" node --input-type=module <<'NODE'
import fs from 'node:fs';
import pg from 'pg';
import {readPrivateToken} from './src/runtime/config.mjs';
import {createCreatorTelegramFetch} from './src/runtime/creatorEgress.mjs';
import {createTelegramBotApi} from './src/telegram/botApi.mjs';
import {createGateOwner} from '../owner/gateOwner.mjs';
const e=process.env;if(e.VIDEOBOT_DB_NAME!=='videobot')throw Error('DATABASE_OWNER_NOT_VERIFIED');
const p=new pg.Pool({host:e.VIDEOBOT_DB_HOST,user:e.VIDEOBOT_DB_USER,database:e.VIDEOBOT_DB_NAME,password:fs.readFileSync('/run/secrets/videobot_db_password','utf8').trim(),max:1});
const net=createCreatorTelegramFetch();
try {
 const api=createTelegramBotApi({token:readPrivateToken(e.VIDEOBOT_TELEGRAM_TOKEN_FILE),fetchImpl:net.fetch,timeoutMs:25000});
 const latest=(await p.query("SELECT r.delivery_key,r.topic_id,r.status receipt_status,r.sale_mode,l.status listing_status,l.seller_user_id,l.paid_video_file_id FROM videobot_post_receipts r JOIN videobot_listings l ON l.listing_id=r.listing_id WHERE r.delivery_key='v26nov24invoice:1'")).rows[0];
 if(!latest||latest.receipt_status!=='sent'||latest.sale_mode!=='invoice'||latest.listing_status!=='published')throw Error('NEW_OFFER_NOT_VERIFIED');
 const purchaseKeys=(await p.query("SELECT DISTINCT delivery_key FROM videobot_stars_ledger WHERE kind='paid' AND delivery_key IS NOT NULL")).rows.map(x=>x.delivery_key);
 if(purchaseKeys.length!==1)throw Error('PAID_KEYS_AMBIGUOUS');
 const buyerStatus=(await p.query("SELECT status FROM videobot_video_legacy_deliveries WHERE delivery_key='v26nov24invoice:1'")).rows;
 if(buyerStatus.length!==1||!['delivery_unknown','delivered'].includes(buyerStatus[0].status))throw Error('BUYER_RIGHTS_RECONCILIATION_PENDING');
 const source=(await p.query("SELECT r.delivery_key,r.listing_id,r.topic_id,r.status,r.free_message_ids,r.paid_message_id,l.seller_user_id,l.paid_video_file_id FROM videobot_post_receipts r JOIN videobot_listings l ON l.listing_id=r.listing_id WHERE r.sale_mode='paid_media' AND r.status='sent' ORDER BY r.delivery_key")).rows;
 if(source.length!==6)throw Error('OLD_OFFER_COUNT_CHANGED');
 if(!source.some(x=>x.delivery_key===purchaseKeys[0]))throw Error('PURCHASED_OLD_OFFER_MISSING');
 if(source.some(x=>x.topic_id!==latest.topic_id||x.seller_user_id!==latest.seller_user_id||x.paid_video_file_id!==latest.paid_video_file_id||x.free_message_ids?.length!==2||!x.paid_message_id))throw Error('OLD_OFFER_OWNER_OR_MEDIA_MISMATCH');
 const owner=await createGateOwner({pool:p,telegramApi:api});
 const topic=await owner.getVerifiedVideoTopic({purpose:'video_sale',sellerId:String(latest.seller_user_id),listingId:'v26nov24invoice'});
 if(topic?.verified!==true||topic?.purpose!=='video_sale'||topic?.board!=='video_chat'||topic?.threadId!==Number(latest.topic_id)||!Number.isSafeInteger(topic.chatId)||topic.chatId>=0)throw Error('TELEGRAM_TOPIC_OWNER_UNVERIFIED');
 const targets=source.filter(x=>!purchaseKeys.includes(x.delivery_key));
 if(targets.length!==source.length-1)throw Error('NONPURCHASED_COUNT_UNEXPECTED');
 let removed=0,kept=1,fullyDeleted=0,failures=0;
 for(const item of targets){
   let ok=true;
   const ids=[Number(item.paid_message_id),...item.free_message_ids.map(Number).reverse()];
   for(const messageId of ids){
     try{
       const result=await api('deleteMessage',{chat_id:topic.chatId,message_id:messageId});
       if(result!==true){ok=false;failures++;console.log('OLD_DELETE='+JSON.stringify({key:item.delivery_key,state:'ack_unknown'}));break}
       removed++;
     }catch{
       ok=false;failures++;console.log('OLD_DELETE='+JSON.stringify({key:item.delivery_key,state:'failed_or_unknown'}));break;
     }
   }
   if(ok){
     fullyDeleted++;
     // Historic delivery receipt and financial ledger never removed.
     const siblingPurchases=purchaseKeys.some(k=>k.startsWith(item.listing_id+':'));
     if(!siblingPurchases){
       await p.query("UPDATE videobot_listings SET status='removed',updated_at=NOW() WHERE listing_id=$1 AND status='published'",[item.listing_id]);
     }
   }
 }
 const afterPaid=(await p.query("SELECT COUNT(*)::int n FROM videobot_stars_ledger WHERE kind='paid'")).rows[0].n;
 const preserve=(await p.query("SELECT COUNT(*)::int n FROM videobot_post_receipts WHERE delivery_key=$1 AND status='sent' AND sale_mode='paid_media'",[purchaseKeys[0]])).rows[0].n;
 if(afterPaid<1||preserve!==1)throw Error('PAID_BUYER_HISTORY_LOST');
 console.log('CLEANUP='+JSON.stringify({preservedPurchasedPosts:kept,nonPurchasedOldPosts:targets.length,fullyDeleted,deletedMessagesAck:removed,failedTargets:failures,historyPreserved:true}));
}finally{await net.close();await p.end()}
NODE
